 public sealed class GestureWindow:Window {
  readonly GestureEngine gestures;readonly KeyboardEngine keyboard;readonly State state;readonly Binding previous;readonly bool paused;readonly Func<IEnumerable<SystemShortcut>> external;readonly Func<ShapeTemplate,Binding,PromptWindow> promptFactory;readonly Button promptAction;
  readonly TextBox name=new TextBox();readonly ComboBox action=new ComboBox(),profile=new ComboBox();readonly Canvas canvas=new Canvas{Height=220,ClipToBounds=true};readonly TextBlock status=Theme.Text("",13,"Muted"),summary=Theme.Text("",13);readonly Button save;ShapeTemplate sample;Binding chosen;
  readonly Polyline traceLine=new Polyline{StrokeThickness=3,StrokeLineJoin=PenLineJoin.Round};
  public Binding Result;
  public GestureWindow(GestureEngine input,KeyboardEngine engine,State data,Func<IEnumerable<SystemShortcut>> sources,Binding old=null,Func<ShapeTemplate,Binding,PromptWindow> createPrompt=null,bool startWithPrompt=false){
   promptFactory=createPrompt;traceLine.SetResourceReference(Shape.StrokeProperty,"Accent");canvas.Children.Add(traceLine);canvas.SizeChanged+=(s,e)=>{if(sample!=null)Draw(sample.Points);};
   canvas.SetResourceReference(Panel.BackgroundProperty,"Surface");gestures=input;keyboard=engine;state=data;previous=old;external=sources;paused=keyboard.Paused;keyboard.ResetPending();keyboard.Paused=true;Style=(Style)Application.Current.FindResource(typeof(Window));Title=old==null?"Add touchpad shape":"Edit touchpad shape";Width=850;Height=820;MinWidth=650;MinHeight=540;WindowStartupLocation=WindowStartupLocation.CenterOwner;Brand.Fit(this);
   var dock=new DockPanel{Margin=new Thickness(24)};Content=dock;var footer=new StackPanel();footer.Children.Add(status);var buttons=new WrapPanel{HorizontalAlignment=HorizontalAlignment.Right,Margin=new Thickness(0,12,0,0)};buttons.Children.Add(Theme.Button("Cancel",()=>DialogResult=false));save=Theme.Button("Save shape shortcut",Commit,true);buttons.Children.Add(save);footer.Children.Add(buttons);DockPanel.SetDock(footer,Dock.Bottom);dock.Children.Add(footer);var form=new StackPanel();dock.Children.Add(new ScrollViewer{Content=form,VerticalScrollBarVisibility=ScrollBarVisibility.Auto});form.Children.Add(Theme.Text("Draw once. Run it with your touchpad.",25));form.Children.Add(Theme.Text("No activation key or button is required. Record a distinct one-finger shape, then pause. A saved shape can run in the background when continuous recognition is enabled.",13,"Muted"));Label(form,"Shortcut name");name.Text=old==null?"New shape shortcut":old.Name;form.Children.Add(name);Label(form,"Profile");profile.DisplayMemberPath="Name";profile.SelectedValuePath="Id";profile.ItemsSource=new[]{new ShortcutProfile{Id="",Name="All profiles"}}.Concat(data.Profiles).ToList();profile.SelectedValue=old==null?data.ActiveProfileId:old.ProfileId;form.Children.Add(profile);
   var recording=new WrapPanel{Margin=new Thickness(0,14,0,10)};recording.Children.Add(Theme.Button("Record shape",()=>{gestures.BeginRecording();status.Text="Move one finger on your touchpad now; pause to finish. The recording starts after a short delay.";},true));recording.Children.Add(Theme.Button("Stop capture",()=>gestures.CancelCapture()));form.Children.Add(recording);form.Children.Add(canvas);form.Children.Add(Theme.Text("Use the touchpad source selected on the Touchpad gestures page. Record a larger shape if the trace is too short.",12,"Muted"));Label(form,"Action to run");action.DisplayMemberPath="Name";action.ItemsSource=data.Bindings.Where(b=>b!=old).Select(b=>new ActionChoice{Binding=b,Name=b.Name+" • "+b.Summary}).ToList();form.Children.Add(action);form.Children.Add(Theme.Button("Create / edit action",EditAction));summary.Margin=new Thickness(0,10,0,0);form.Children.Add(summary);
   promptAction=Theme.Button("Describe action with prompt",PromptAction,true);promptAction.Margin=new Thickness(0,10,0,8);form.Children.Insert(form.Children.IndexOf(summary),promptAction);if(startWithPrompt){Title="Create touchpad shortcut with prompt";((TextBlock)form.Children[1]).Text="1. Record your shape.  2. Describe its action with a prompt.  3. Review and save. No keyboard trigger is required.";}
   if(old!=null){sample=old.Gesture.Copy();chosen=old.Copy();Draw(sample.Points);}action.SelectionChanged+=(s,e)=>{var value=action.SelectedItem as ActionChoice;if(value!=null){chosen=value.Binding.Copy();Refresh();}};name.TextChanged+=(s,e)=>Refresh();profile.SelectionChanged+=(s,e)=>Refresh();gestures.Trace+=Trace;gestures.Recorded+=Recorded;gestures.StatusChanged+=Message;Closed+=(s,e)=>{gestures.Trace-=Trace;gestures.Recorded-=Recorded;gestures.StatusChanged-=Message;gestures.CancelCapture();keyboard.Paused=paused;};Refresh();
  }
  static void Label(Panel form,string label){var text=Theme.Text(label,12,"Muted");text.Margin=new Thickness(0,12,0,5);form.Children.Add(text);}
  void Trace(IList<GesturePoint> points){Draw(points);}
  void Message(string message){status.Text=message;}
  void Recorded(IList<GesturePoint> points){sample=new ShapeTemplate{Points=points.Select(p=>new GesturePoint(p.X,p.Y)).ToList()};Draw(points);Refresh();}
  void Draw(IList<GesturePoint> points){var normalized=ShapeRecognition.Normalize(points);if(normalized.Count==0){traceLine.Points.Clear();return;}double width=canvas.ActualWidth>40?canvas.ActualWidth:700,height=canvas.Height,minX=normalized.Min(p=>p.X),maxX=normalized.Max(p=>p.X),minY=normalized.Min(p=>p.Y),maxY=normalized.Max(p=>p.Y);double scale=Math.Min((width-36)/Math.Max(0.001,maxX-minX),(height-36)/Math.Max(0.001,maxY-minY));traceLine.Points=new PointCollection(normalized.Select(p=>new Point(width/2+(p.X-(minX+maxX)/2)*scale,height/2+(p.Y-(minY+maxY)/2)*scale)));}
  Binding Draft(){if(sample==null)throw new ArgumentException("Record a shape first.");if(chosen==null)throw new ArgumentException("Choose an action or create one.");var result=chosen.Copy();result.Id=previous==null?Guid.NewGuid().ToString():previous.Id;result.Name=name.Text.Trim();result.Gesture=sample.Copy();result.Key=result.Mods=result.PrefixKey=0;result.PassThrough=false;result.Enabled=previous==null||previous.Enabled;result.ProfileId=profile.SelectedValue as string??"";return result;}
  void Refresh(){if(save==null)return;if(promptAction!=null)promptAction.IsEnabled=sample!=null;summary.Text=chosen==null?"No action selected.":chosen.Kind+" • "+chosen.Summary;try{var draft=Draft();string error=Rules.Validate(draft,state.Bindings);save.IsEnabled=error==null;status.Text=error??"Ready. The shape will run after you draw it and pause.";}catch(ArgumentException error){save.IsEnabled=false;status.Text=error.Message;}}
  void PromptAction(){if(sample==null){status.Text="Record a shape, then describe its action.";return;}gestures.CancelCapture();Binding old=chosen!=null&&(chosen.Kind=="Workflow"||chosen.Kind=="Browser website")?chosen.Copy():null;if(old!=null){old.Gesture=sample.Copy();old.Key=old.Mods=old.PrefixKey=0;old.ProfileId=profile.SelectedValue as string??"";}var dialog=promptFactory!=null?promptFactory(sample.Copy(),old):new PromptWindow(keyboard,new Binding[0],state.ApplicationPaths,previous:old,configuredModel:state.ModelPath,profiles:state.Profiles,activeProfile:state.ActiveProfileId,savedPreferences:state.Preferences,preferGpu:state.UseGpu??true,modelOptions:state.ModelOptions,gesture:sample);dialog.Owner=this;dialog.ProfileId=profile.SelectedValue as string??"";if(dialog.ShowDialog()==true){chosen=dialog.Result.Copy();if(previous==null&&name.Text=="New shape shortcut")name.Text=chosen.Name;Refresh();}}
  void EditAction(){if(sample==null){status.Text="Record the shape before editing its action.";return;}var draft=chosen==null?new Binding{Name=name.Text.Trim(),Kind="Send key",SendKey=67,SendMods=2}:chosen.Copy();draft.Gesture=sample.Copy();draft.Key=draft.Mods=draft.PrefixKey=0;draft.Name=name.Text.Trim();draft.Enabled=false;if(draft.Kind=="Workflow"){var macro=new MacroWindow(keyboard,new Binding[0],state.Profiles,state.ActiveProfileId,external,draft,actionOnly:true){Owner=this};if(macro.ShowDialog()==true){chosen=macro.Result;Refresh();}return;}var editor=new Editor(keyboard,null,new Binding[0],state.ApplicationPaths,draft,external,state.Profiles,state.ActiveProfileId,actionOnly:true){Owner=this};if(editor.ShowDialog()==true){chosen=editor.Result;Refresh();}}
  void Commit(){try{var draft=Draft();string error=Rules.Validate(draft,state.Bindings);if(error!=null){status.Text=error;return;}Result=draft;DialogResult=true;}catch(Exception error){status.Text=error.Message;}}
  internal void RecordForTest(IList<GesturePoint> points){Recorded(points);}
  internal void ActionForTest(Binding binding){chosen=binding.Copy();Refresh();}
  internal Binding DraftForTest(){return Draft();}
  internal bool SaveVisibleForTest {get{return save.IsVisible;}}
  internal void SaveForTest(){save.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));}
  internal void PromptForTest(){promptAction.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));}
  internal bool CanPromptForTest {get{return promptAction.IsEnabled;}}
  internal bool TraceFitsForTest {get{return traceLine.Points.All(p=>p.X>=17&&p.X<=canvas.ActualWidth-17&&p.Y>=17&&p.Y<=canvas.Height-17);}}
  sealed class ActionChoice {public Binding Binding;public string Name{get;set;}}
 }
 public partial class MainWindow {
  GestureEngine gestures;readonly TextBlock gestureStatus=Theme.Text("",12,"Muted");
  void InitializeGestures(){if(state.Gestures==null)state.Gestures=new GestureOptions();gestures=new GestureEngine(engine,()=>state,()=>Profiles.Effective(state));gestures.StatusChanged+=message=>gestureStatus.Text=message;gestures.DeviceDetected+=device=>{state.Gestures.Device=device;Save();gestureStatus.Text=string.IsNullOrEmpty(device)?"Precision Touchpad selected.":"Pointer source selected for this touchpad.";};}
  void OpenGesture(Binding binding=null,bool withPrompt=false){guide.Hide();gestures.CancelCapture();var dialog=new GestureWindow(gestures,engine,state,()=>AllSystem(),binding,(shape,old)=>CreatePromptWindow(old==null?"":old.AppPath,old,shape),withPrompt){Owner=this};if(dialog.ShowDialog()==true)StoreBinding(dialog.Result,binding);gestures.Refresh();}
  UIElement GesturePanel(){var form=new StackPanel();form.Children.Add(Theme.Text("Touchpad shapes, always ready",25));form.Children.Add(Theme.Text("Draw a saved one-finger shape and pause. No hotkey, mouse button or activation tap is needed. Only confident matches run, in their assigned profile and application scope.",14,"Muted"));var enabled=new CheckBox{Content="Continuously recognize touchpad shapes",IsChecked=state.Gestures.Enabled};enabled.Checked+=(s,e)=>SetGestureEnabled(true);enabled.Unchecked+=(s,e)=>SetGestureEnabled(false);form.Children.Add(enabled);
   var bar=new WrapPanel{Margin=new Thickness(0,10,0,10)};bar.Children.Add(Theme.Button("Detect my touchpad",()=>gestures.BeginCalibration()));bar.Children.Add(Theme.Button("Use Windows Precision Touchpad",()=>{gestures.CancelCapture();state.Gestures.Device="";Save();Render();}));bar.Children.Add(Theme.Button("Add a shape",()=>OpenGesture()));bar.Children.Add(Theme.Button("Create with prompt",()=>OpenGesture(null,true),true));form.Children.Add(bar);form.Children.Add(Theme.Text(string.IsNullOrEmpty(state.Gestures.Device)?"Source: Windows Precision Touchpad input":"Source: calibrated pointer device",13));form.Children.Add(Theme.Text("For a legacy driver, click Detect my touchpad and move only your touchpad. Calibration selects the Windows pointer source; the app cannot identify vendor-only inputs that Windows does not expose. Normal cursor movement continues while listening. Switch to a target application to try a saved shape; recognition is suspended in Makro+ itself.",12,"Muted"));Detach(gestureStatus);gestureStatus.Text=gestures.Status;gestureStatus.Margin=new Thickness(0,10,0,14);form.Children.Add(gestureStatus);
   var options=new WrapPanel();var pause=new ComboBox{Width=145,ItemsSource=new[]{400,600,800,1000,1400},SelectedItem=state.Gestures.PauseMilliseconds};options.Children.Add(Theme.Text("Pause to finish (ms)  ",13));options.Children.Add(pause);var score=new ComboBox{Width=120,ItemsSource=new[]{0.82,0.86,0.88,0.92,0.96},SelectedItem=state.Gestures.MinimumScore};options.Children.Add(Theme.Text("  Match confidence  ",13));options.Children.Add(score);options.Children.Add(Theme.Button("Save settings",()=>{if(pause.SelectedItem is int)state.Gestures.PauseMilliseconds=(int)pause.SelectedItem;if(score.SelectedItem is double)state.Gestures.MinimumScore=(double)score.SelectedItem;gestures.CancelCapture();Save();gestureStatus.Text="Gesture settings saved.";}));form.Children.Add(options);
   foreach(var binding in state.Bindings.Where(b=>b.Gesture!=null)){var item=binding;var row=new StackPanel{Margin=new Thickness(0,10,0,0)};row.Children.Add(Theme.Text(item.Name,18));row.Children.Add(Theme.Text(item.Summary,12,"Muted"));row.Children.Add(Theme.Text(Profiles.Describe(item,state.Profiles,state.ActiveProfileId,state.Paused),12,"Muted"));var actions=new WrapPanel{Margin=new Thickness(0,8,0,0)};actions.Children.Add(Theme.Button("Edit shape / action",()=>OpenGesture(item)));actions.Children.Add(Theme.Button(item.Enabled?"Disable":"Enable",()=>SetActivation(item)));actions.Children.Add(Theme.Button("Delete",()=>{if(MessageBox.Show(this,"Delete this shape shortcut?","Touchpad gestures",MessageBoxButton.YesNo)!=MessageBoxResult.Yes)return;int index=state.Bindings.IndexOf(item);state.Bindings.RemoveAt(index);if(!Save())state.Bindings.Insert(index,item);gestures.Refresh();Render();}));row.Children.Add(actions);var card=Theme.Card(row);card.Margin=new Thickness(0,10,0,0);form.Children.Add(card);}
   if(!state.Bindings.Any(b=>b.Gesture!=null))form.Children.Add(Theme.Text("No shapes saved yet. Detect your touchpad, add a shape and select its action.",14));return new ScrollViewer{Content=form,VerticalScrollBarVisibility=ScrollBarVisibility.Auto};
  }
  void SetGestureEnabled(bool enabled){bool old=state.Gestures.Enabled;state.Gestures.Enabled=enabled;gestures.CancelCapture();if(!Save())state.Gestures.Enabled=old;gestures.Refresh();}
